import{_ as a,c as d,o as e,a2 as o}from"./chunks/framework.CHomSxuB.js";const g=JSON.parse('{"title":"1. 首板先锋：唯一还活着的线（Step 1 回测 + Step 4 前向）","description":"","frontmatter":{},"headers":[],"relativePath":"A股量化验证/1-首板先锋.md","filePath":"A股量化验证/1-首板先锋.md"}'),r={name:"A股量化验证/1-首板先锋.md"};function s(n,t,l,i,h,p){return e(),d("div",null,t[0]||(t[0]=[o(`<h1 id="_1-首板先锋-唯一还活着的线-step-1-回测-step-4-前向" tabindex="-1">1. 首板先锋：唯一还活着的线（Step 1 回测 + Step 4 前向） <a class="header-anchor" href="#_1-首板先锋-唯一还活着的线-step-1-回测-step-4-前向" aria-label="Permalink to &quot;1. 首板先锋：唯一还活着的线（Step 1 回测 + Step 4 前向）&quot;">​</a></h1><blockquote><p>全系统唯一在回测层跑出显著正期望、且正在<strong>前向验证</strong>的底座。 状态：🔴 前向追踪中（截至 2026-09-02，12 个交易日 / 7 个可成交样本，未到评估点）</p></blockquote><h2 id="假设" tabindex="-1">假设 <a class="header-anchor" href="#假设" aria-label="Permalink to &quot;假设&quot;">​</a></h2><p><strong>&quot;全市场第一个封死涨停的主板票，次日有超额收益&quot;</strong>——赚的是秒级速度差： 信息同步到所有人之前，最早封板的那只票代表当日最强合力方向。</p><h2 id="信号定义-冻结-不可改" tabindex="-1">信号定义（冻结，不可改） <a class="header-anchor" href="#信号定义-冻结-不可改" aria-label="Permalink to &quot;信号定义（冻结，不可改）&quot;">​</a></h2><ul><li>宇宙：纯主板（60xxxx / 00xxxx），剔除 ST/*ST、剔除新股</li><li>每日信号：涨停池中 <code>first_limit_up_time</code>（秒级 epoch）最早者</li><li>平局：<code>order_amount</code>（封单额）降序 → <code>code</code> 升序</li><li>执行：T 日盘中以涨停价排板买入 → T+1 收盘卖出（双边 0.35% 摩擦）</li></ul><h2 id="step-1-回测结果-v0-4-2-口径-243-交易日" tabindex="-1">Step 1 回测结果（v0.4.2 口径，243 交易日） <a class="header-anchor" href="#step-1-回测结果-v0-4-2-口径-243-交易日" aria-label="Permalink to &quot;Step 1 回测结果（v0.4.2 口径，243 交易日）&quot;">​</a></h2><p>判定子集：<strong>纯主板可成交样本 n=95</strong>，bootstrap 10,000 次按日重采样，BH-FDR Q=0.05。</p><table tabindex="0"><thead><tr><th>指标</th><th>n</th><th>mean</th><th>双尾 p</th><th>BH 显著</th></tr></thead><tbody><tr><td>Ev(Close) 收盘收益</td><td>95</td><td><strong>+0.0288</strong></td><td>0.0000</td><td>✅</td></tr><tr><td>超额 vs 中证1000</td><td>95</td><td><strong>+0.0302</strong></td><td>0.0002</td><td>✅</td></tr></tbody></table><p><strong>判定：有 edge（进入 Step 4）</strong> —— 注意这是<strong>回测层</strong>判决，真实可交易性要靠前向验证回答。</p><h2 id="关键事实-可成交率只有-43-6" tabindex="-1">关键事实：可成交率只有 43.6% <a class="header-anchor" href="#关键事实-可成交率只有-43-6" aria-label="Permalink to &quot;关键事实：可成交率只有 43.6%&quot;">​</a></h2><p>241 个有信号的交易日里，仅 105 天次日能正常买进（<code>n_fill=105</code>，executable_rate=43.6%）； 剩余 56.4% 因 T+1 一字/近一字开盘（≥基准×1.095）被判定 <strong>UNFILLED —— 散户通道根本排不进</strong>。</p><table tabindex="0"><thead><tr><th>全样本（Paper，含不可成交）</th><th>n=241</th><th>Ev(Close) <strong>+0.0697</strong></th></tr></thead><tbody><tr><td>纯主板可成交（tradable，判定基准）</td><td>n=95</td><td>Ev(Close) <strong>+0.0288</strong></td></tr></tbody></table><p>最赚钱的那批超级先锋（秒板/一字）恰恰是散户买不到的；能买到的 43.6% 是 <strong>分歧偏大、封单偏弱的次强标的</strong>。即便如此，剔除&quot;买不到幻觉&quot;后可成交样本 依然显著为正——<strong>alpha 不是靠纸上富贵堆出来的</strong>。这是 Step 4 敢继续跑下去的理由。</p><h2 id="step-4-前向追踪-真金白银的账本-但不花真钱" tabindex="-1">Step 4 前向追踪（真金白银的账本，但不花真钱） <a class="header-anchor" href="#step-4-前向追踪-真金白银的账本-但不花真钱" aria-label="Permalink to &quot;Step 4 前向追踪（真金白银的账本，但不花真钱）&quot;">​</a></h2><p>回测会骗人（过拟合/幸存者偏差/&quot;早知道&quot;）。Step 4 换个玩法：从 2026-08-19 起， 每天收盘后按冻结规则记录当日信号，<strong>次日 15:15 自动结算真实结果</strong>，只记账不花钱， 攒够样本后按<strong>事先冻结的生死线</strong>判决。</p><p>状态机（冻结判准，V0.4.3 顺延修正）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>终审时机：20 交易日内可成交 n≥8 即评估；不足 8 顺延，最多 40 交易日强制评估</span></span>
<span class="line"><span>PASS = 可成交 n≥8 ∧ 净 Ev&gt;0 ∧ 累计超额(vs 000852) &gt; -2% ∧ 未熔断</span></span>
<span class="line"><span>熔断 = 连续 3 个可成交信号亏损 → KILLED（立即停机人工复核）</span></span></code></pre></div><h3 id="当前进度-as-of-2026-09-02" tabindex="-1">当前进度（as_of 2026-09-02） <a class="header-anchor" href="#当前进度-as-of-2026-09-02" aria-label="Permalink to &quot;当前进度（as_of 2026-09-02）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>数值</th><th>生死线</th><th>状态</th></tr></thead><tbody><tr><td>窗口</td><td>12 交易日</td><td>20（可顺延至 40）</td><td>顺延中</td></tr><tr><td>已结算可成交样本</td><td><strong>7</strong></td><td>≥8 才评估</td><td>差 1 笔</td></tr><tr><td>净 Ev（扣 0.35% 摩擦）</td><td><strong>+4.73%</strong></td><td>&gt;0</td><td>暂优</td></tr><tr><td>胜率</td><td>85.7%（6/7）</td><td>—</td><td>暂优</td></tr><tr><td>累计超额 vs 中证1000</td><td><strong>+5.90%</strong></td><td>&gt;-2%</td><td>暂优</td></tr><tr><td>最大回撤</td><td>5.21%</td><td>&lt;8% 熔断</td><td>安全</td></tr><tr><td>连续大亏</td><td>0 / 3</td><td>≥3 熔断</td><td>安全</td></tr><tr><td><strong>判定</strong></td><td>—</td><td>—</td><td><strong>顺延中（未到评估点）</strong></td></tr></tbody></table><p>7 笔明细：学大教育 +9.64%、日丰股份 −5.21%（唯一亏损，也是最大回撤来源）、 汉森制药 +9.66%、协鑫能科 +1.64%、湖南黄金 +6.68%、我爱我家 +9.65%、海鸥住工 +1.07%。</p><blockquote><p>⚠️ 走势好看 ≠ 已经赢了：样本只有 7 笔，远不到判卷时刻。 Step 4 的意义恰在于——不在第 5 笔宣布胜利，也不在第 3 笔亏损时恐慌，一切等凑够样本。</p></blockquote><h2 id="已在运行中暴露并修复的工程问题" tabindex="-1">已在运行中暴露并修复的工程问题 <a class="header-anchor" href="#已在运行中暴露并修复的工程问题" aria-label="Permalink to &quot;已在运行中暴露并修复的工程问题&quot;">​</a></h2><ul><li><strong>注释与实现打架</strong>：docstring 写&quot;T+1 开盘买入&quot;，实现却是&quot;T 收盘成本、T+1 收盘卖出&quot;。 纯文案修复，不动公式 → 见《6. 数据洁净度审计》。</li><li><strong>历史账本口径审计</strong>：对全部 12 笔 SIGNAL 逐笔反推隐含成本价与独立行情重拉比对， 11 笔全 PASS、1 笔待结算 → 历史数据干净，无脏数据回填需求。</li></ul><h2 id="已知物理局限-写进终审白皮书的清单项" tabindex="-1">已知物理局限（写进终审白皮书的清单项） <a class="header-anchor" href="#已知物理局限-写进终审白皮书的清单项" aria-label="Permalink to &quot;已知物理局限（写进终审白皮书的清单项）&quot;">​</a></h2><ul><li>T+1 一字跌停时仍按收盘价记账（实际可能卖不出/卖得更低）→ 轻微多头乐观偏差； 协议冻结期不修，待终审白皮书列入 Known Limitations。</li></ul>`,26)]))}const u=a(r,[["render",s]]);export{g as __pageData,u as default};
